import React from 'react';
import { Link } from 'react-router-dom';

const Sidebar = () => {
  return (
    <div style={{ width: '250px', backgroundColor: '#f4f4f4', padding: '20px' }}>
      <ul>
        <li><Link to="/cadastro/alunos">Cadastro de Alunos</Link></li>
        <li><Link to="/cadastro/disciplinas">Cadastro de Disciplinas</Link></li>
        <li><Link to="/cadastro/professores">Cadastro de Professores</Link></li>
        <li><Link to="/cadastro/salas">Cadastro de Salas</Link></li>
        <li><Link to="/cadastro/turmas">Cadastro de Turmas</Link></li>
        <li><Link to="/consulta/alunos">Consulta de Alunos</Link></li>
        <li><Link to="/consulta/disciplinas">Consulta de Disciplinas</Link></li>
        <li><Link to="/consulta/professores">Consulta de Professores</Link></li>
        <li><Link to="/consulta/salas">Consulta de Salas</Link></li>
        <li><Link to="/consulta/turmas">Consulta de Turmas</Link></li>
      </ul>
    </div>
  );
}

export default Sidebar;
